async def on_finish(self, reason="Call ended"):
    try:
        self.ctx.shutdown(reason=reason)
    except Exception as e:
        logger.error(f"Error shutting down Voice Agent: {e}")

### Helper functions
def load_script(script_data: dict) -> CallScript:
    """Load a call script from dictionary data"""
    try:
        script = CallScript(**script_data)
        return script
    except Exception as e:
        logger.error(f"Failed to load script: {e}")
        raise


def load_script_from_file(file_path: str) -> CallScript:
    """Load a call script from JSON file"""
    with open(file_path) as f:
        data = json.load(f)
    return load_script(data)


def entrypoint_generator(
    call_script: CallScript, config: VoiceAgentConfig
) -> Callable[[JobContext], Awaitable[None]]:
    async def entrypoint(ctx: JobContext):
        """Main entrypoint for LiveKit agent"""
        # Create and initialize agent
        voice_agent_manager = VoiceAgentManager(ctx, call_script, config)
        try:
            # Start conversation session
            await voice_agent_manager.start_session()

