import logging
from typing import Any

import jsonata


logger = logging.getLogger(__name__)


class CandidateDatapointValidator:
    def __init__(self, data: dict[str, Any]):
        self.data = data

    def validate(self, raw_expression: str) -> bool:
        """Validate a candidate datapoint using a JSONata expression."""
        try:
            expression = jsonata.Jsonata(raw_expression)
            result = expression.evaluate(self.data)
            return bool(result)
        except Exception as e:
            logger.exception(
                f"Unable to evaluate {raw_expression} with data {self.data}: {e}"
            )
            return False
